mapper.select:
SELECT u.class_name as class_name, COUNT(a.id) as award_count FROM award a JOIN team_info ti ON a.team_id = ti.id JOIN team_member_teacher tmt ON ti.id = tmt.team_id JOIN team_member_student tms ON ti.id = tms.team_id JOIN user_info u ON tms.student_id = u.id WHERE tmt.teacher_id = #{teacherId}
AND u.major = #{major}
AND u.class_name = #{sClass}
AND ti.type = #{projectType}
AND ti.year = #{year}
GROUP BY u.class_name ORDER BY award_count DESC
